  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "D617, the closest analogue (Morgan 0.72) sharing the verapamil-like nitrile/isopropyl/dimethoxyphenyl core, showed very low rat brain uptake (<0.1% ID/g) by PET and was identified as a P-gp substrate; brain radioactivity increased ~3-fold after P-gp inhibition, demonstrating that this scaffold has poor intrinsic BBB access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A dimethoxyphenethyl-containing NBPEA compound crossed the zebrafish BBB and reached detectable brain levels, indicating that the dimethoxyphenethyl motif can be CNS-permeable in simpler structures.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "WOBE437, which contains a dimethoxyphenethyl group, achieved brain-to-plasma Kp values >1 in mice, supporting CNS bioavailability for some related phenethylamine analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: the closest and most directly transferable evidence (D617, Morgan 0.72) shows very low brain uptake and P-gp-mediated efflux for the verapamil-like core present in the query (norverapamil). Weaker, less transferable evidence from simpler dimethoxyphenethyl analogues showing BBB permeability does not outweigh this direct close-analogue measurement.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for norverapamil itself.",
    "Zebrafish and PET uptake results for more distant analogues are qualitative and do not quantify unbound brain exposure.",
    "P-gp efflux magnitude for the full query molecule is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

